package mekanism.common.content.network.transmitter;

import java.util.Collection;
import java.util.UUID;
import mekanism.api.IContentsListener;
import mekanism.api.SerializationConstants;
import mekanism.api.heat.IHeatCapacitor;
import mekanism.api.heat.IHeatHandler;
import mekanism.common.block.attribute.Attribute;
import mekanism.common.capabilities.Capabilities;
import mekanism.common.capabilities.heat.CachedAmbientTemperature;
import mekanism.common.capabilities.heat.ITileHeatHandler;
import mekanism.common.capabilities.heat.VariableHeatCapacitor;
import mekanism.common.component.containers.type.ContainerType;
import mekanism.common.content.network.HeatNetwork;
import mekanism.common.lib.Color;
import mekanism.common.lib.transmitter.TransmissionType;
import mekanism.common.lib.transmitter.acceptor.AcceptorCache;
import mekanism.common.tier.ConductorTier;
import mekanism.common.tile.transmitter.TileEntityTransmitter;
import mekanism.common.upgrade.transmitter.ThermodynamicConductorUpgradeData;
import mekanism.common.upgrade.transmitter.TransmitterUpgradeData;
import net.minecraft.core.Direction;
import net.minecraft.core.Holder;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.neoforged.neoforge.transfer.transaction.TransactionContext;
import org.jspecify.annotations.Nullable;

public class ThermodynamicConductor extends Transmitter<IHeatHandler, HeatNetwork, ThermodynamicConductor> implements ITileHeatHandler, IContentsListener,
      IUpgradeableTransmitter<ThermodynamicConductorUpgradeData> {

    private final CachedAmbientTemperature ambientTemperature = new CachedAmbientTemperature(this::getLevel, this::getBlockPos);
    public final ConductorTier tier;
    //Default to negative one, so we know we need to calculate it when needed
    private double clientTemperature = -1;
    public final VariableHeatCapacitor buffer;

    public ThermodynamicConductor(Holder<Block> blockProvider, TileEntityTransmitter tile) {
        this.tier = Attribute.getTierNN(blockProvider, ConductorTier.class);
        super(tile, TransmissionType.HEAT);
        buffer = VariableHeatCapacitor.create(tier.getHeatCapacity(), tier::getInverseConduction, tier::getInverseConductionInsulation, ambientTemperature, this);
    }

    @Override
    protected AcceptorCache<IHeatHandler> createAcceptorCache() {
        return new AcceptorCache<>(getTransmitterTile(), Capabilities.HEAT);
    }

    @Override
    public ConductorTier getTier() {
        return tier;
    }

    @Override
    public HeatNetwork createEmptyNetworkWithID(UUID networkID) {
        return new HeatNetwork(networkID);
    }

    @Override
    public HeatNetwork createNetworkByMerging(Collection<HeatNetwork> networks) {
        return new HeatNetwork(networks);
    }

    @Override
    public void takeShare(@Nullable TransactionContext transaction) {
    }

    @Override
    protected boolean isValidAcceptor(@Nullable BlockEntity tile, Direction side) {
        //Note: We intentionally do not call super here as other elements in the network are intentionally acceptors
        return getAcceptorCache().getConnectedAcceptor(side) != null;
    }

    @Override
    public ThermodynamicConductorUpgradeData getUpgradeData() {
        return new ThermodynamicConductorUpgradeData(redstoneReactive, getConnectionTypesRaw(), buffer.getHeat());
    }

    @Override
    public boolean dataTypeMatches(TransmitterUpgradeData data) {
        return data instanceof ThermodynamicConductorUpgradeData;
    }

    @Override
    public void parseUpgradeData(ThermodynamicConductorUpgradeData data, TransactionContext transaction) {
        redstoneReactive = data.redstoneReactive;
        setConnectionTypesRaw(data.connectionTypes);
        buffer.setHeat(data.heat, transaction);
    }

    @Override
    public void write(ValueOutput output) {
        super.write(output);
        ContainerType.HEAT.saveTo(output, buffer);
    }

    @Override
    public void read(ValueInput input) {
        super.read(input);
        ContainerType.HEAT.readFrom(input, buffer);
    }

    @Override
    public void writeReducedUpdatedTag(ValueOutput output) {
        super.writeReducedUpdatedTag(output);
        output.putDouble(SerializationConstants.HEAT_STORED, buffer.getHeat());
    }

    @Override
    public boolean handleUpdateTag(ValueInput input) {
        boolean refreshModelData = super.handleUpdateTag(input);
        buffer.setHeat(input.getDoubleOr(SerializationConstants.HEAT_STORED, buffer.getHeat()), null);
        return refreshModelData;
    }

    public Color getBaseColor() {
        return tier.getBaseColor();
    }

    @Override
    public IHeatCapacitor getHeatCapacitor(@Nullable Direction side) {
        return buffer;
    }

    public double getTemperature() {
        return buffer.getTemperature();
    }

    @Override
    public void onContentsChanged() {
        if (!isClientSide()) {
            if (clientTemperature == -1) {
                clientTemperature = ambientTemperature.getAsDouble();
            }
            if (Math.abs(buffer.getTemperature() - clientTemperature) > (buffer.getTemperature() / 20)) {
                clientTemperature = buffer.getTemperature();
                getTransmitterTile().sendUpdatePacket();
            }
        }
        getTransmitterTile().setChanged();
    }

    @Override
    public double getAmbientTemperature(Direction side) {
        return ambientTemperature.getTemperature(side);
    }

    @Nullable
    @Override
    public IHeatHandler getAdjacent(Direction side) {
        if (connectionMapContainsSide(getAllCurrentConnections(), side)) {
            //Note: We use the acceptor cache as the heat network is different and the transmitters count the other transmitters in the
            // network as valid acceptors, which means we don't have to differentiate between acceptors and other transmitters here
            return getAcceptorCache().getConnectedAcceptor(side);
        }
        return null;
    }

    @Override
    public boolean countsAsAdjacent(Direction side) {
        //Heat transmitter to heat transmitter, don't count as "adjacent transfer"
        return !hasTransmitterNetwork() || getTransmitterNetworkNN().getTransmitter(getBlockPos().relative(side)) != null;
    }
}

package mekanism.common.content.network;

import java.util.Collection;
import java.util.UUID;
import mekanism.api.heat.HeatAPI;
import mekanism.api.heat.HeatAPI.HeatTransfer;
import mekanism.api.heat.IHeatHandler;
import mekanism.common.MekanismLang;
import mekanism.common.content.network.transmitter.ThermodynamicConductor;
import mekanism.common.lib.transmitter.DynamicNetwork;
import mekanism.common.util.MekanismUtils;
import mekanism.common.util.UnitDisplayUtils.TemperatureUnit;
import net.minecraft.network.chat.Component;
import net.neoforged.neoforge.transfer.transaction.Transaction;

public class HeatNetwork extends DynamicNetwork<IHeatHandler, HeatNetwork, ThermodynamicConductor> {

    private double meanTemp = HeatAPI.AMBIENT_TEMP;
    private double heatLost;
    private double heatTransferred;

    public HeatNetwork(UUID networkID) {
        super(networkID);
    }

    public HeatNetwork(Collection<HeatNetwork> networks) {
        this(UUID.randomUUID());
        adoptAllAndRegister(networks);
    }

    @Override
    public Component getStoredInfo() {
        return MekanismLang.HEAT_NETWORK_STORED.translate(MekanismUtils.getTemperatureDisplay(meanTemp, TemperatureUnit.KELVIN, true));
    }

    @Override
    public Component getFlowInfo() {
        Component transferred = MekanismUtils.getTemperatureDisplay(heatTransferred, TemperatureUnit.KELVIN, false);
        Component lost = MekanismUtils.getTemperatureDisplay(heatLost, TemperatureUnit.KELVIN, false);
        if (heatTransferred + heatLost == 0) {
            return MekanismLang.HEAT_NETWORK_FLOW.translate(transferred, lost);
        }
        return MekanismLang.HEAT_NETWORK_FLOW_EFFICIENCY.translate(transferred, lost,
              MekanismLang.GENERIC_PERCENT.translate(Math.round(heatTransferred / (heatTransferred + heatLost) * 10_000) / 100F));
    }

    @Override
    public void onUpdate() {
        super.onUpdate();
        double newSumTemp = 0, newHeatLost = 0, newHeatTransferred = 0;
        Collection<ThermodynamicConductor> transmitters = getTransmitters();
        try (Transaction transaction = Transaction.openRoot()) {
            for (ThermodynamicConductor transmitter : transmitters) {
                HeatTransfer transfer = transmitter.simulate(transaction);
                newHeatTransferred += transfer.adjacentTransfer();
                newHeatLost += transfer.environmentTransfer();
            }
            transaction.commit();
        }
        //After we updated the heat values of all the transmitters, we need to update the temperatures
        // we do this after instead of when iterating initially so that if heat is transferred from one
        // conductor to one we already updated then we want it to have the proper total temperature
        for (ThermodynamicConductor transmitter : transmitters) {
            newSumTemp += transmitter.getTemperature();
        }
        heatLost = newHeatLost;
        heatTransferred = newHeatTransferred;
        //TODO - 26.3 (heat): Is there a worry that the transmitter collection is empty?
        meanTemp = newSumTemp / transmitters.size();
    }

    @Override
    public String toString() {
        return "[HeatNetwork] " + transmittersSize() + " transmitters, " + getAcceptorCount() + " acceptors.";
    }

    @Override
    public Component getTextComponent() {
        return MekanismLang.NETWORK_DESCRIPTION.translate(MekanismLang.HEAT_NETWORK, transmittersSize(), getAcceptorCount());
    }
}

package mekanism.common.capabilities.heat;

import java.util.function.DoubleSupplier;
import mekanism.api.IContentsListener;
import mekanism.api.MekanismPreconditions;
import mekanism.api.heat.HeatAPI;
import org.jspecify.annotations.Nullable;

public class VariableHeatCapacitor extends BasicHeatCapacitor {

    private final DoubleSupplier conductionCoefficientSupplier;
    private final DoubleSupplier insulationCoefficientSupplier;

    public static VariableHeatCapacitor create(double heatCapacity, @Nullable DoubleSupplier ambientTempSupplier, @Nullable IContentsListener listener) {
        return create(heatCapacity, () -> HeatAPI.DEFAULT_INVERSE_CONDUCTION, () -> HeatAPI.DEFAULT_INVERSE_INSULATION, ambientTempSupplier, listener);
    }

    public static VariableHeatCapacitor create(double heatCapacity, DoubleSupplier conductionCoefficient, DoubleSupplier insulationCoefficient,
          @Nullable DoubleSupplier ambientTempSupplier, @Nullable IContentsListener listener) {
        MekanismPreconditions.checkHeatCapacity(heatCapacity);
        return new VariableHeatCapacitor(heatCapacity, conductionCoefficient, insulationCoefficient, ambientTempSupplier, listener);
    }

    protected VariableHeatCapacitor(double heatCapacity, DoubleSupplier conductionCoefficient, DoubleSupplier insulationCoefficient,
          @Nullable DoubleSupplier ambientTempSupplier, @Nullable IContentsListener listener) {
        super(heatCapacity, conductionCoefficient.getAsDouble(), insulationCoefficient.getAsDouble(), ambientTempSupplier, listener);
        this.conductionCoefficientSupplier = conductionCoefficient;
        this.insulationCoefficientSupplier = insulationCoefficient;
    }

    @Override
    public double getInverseConduction() {
        return Math.max(1, conductionCoefficientSupplier.getAsDouble());
    }

    @Override
    public double getInverseInsulation() {
        return insulationCoefficientSupplier.getAsDouble();
    }
}

package mekanism.common.capabilities.heat;

import java.util.function.DoubleSupplier;
import mekanism.api.IContentsListener;
import mekanism.api.MekanismPreconditions;
import mekanism.api.heat.HeatAPI;
import mekanism.api.heat.IHeatCapacitor;
import mekanism.common.component.containers.heat.HeatCapacitorData;
import net.minecraft.util.Mth;
import net.neoforged.neoforge.transfer.transaction.SnapshotJournal;
import net.neoforged.neoforge.transfer.transaction.Transaction;
import net.neoforged.neoforge.transfer.transaction.TransactionContext;
import org.jspecify.annotations.Nullable;

public class BasicHeatCapacitor extends SnapshotJournal<HeatCapacitorData> implements IHeatCapacitor {

    @Nullable
    private final IContentsListener listener;

    @Nullable
    private final DoubleSupplier ambientTempSupplier;
    private final double inverseConductionCoefficient;
    private final double inverseInsulationCoefficient;

    // set to ambient * heat capacity by default
    private double storedHeat = -1;
    private double heatCapacity;

    public static BasicHeatCapacitor create(double heatCapacity, @Nullable DoubleSupplier ambientTempSupplier, @Nullable IContentsListener listener) {
        return create(heatCapacity, HeatAPI.DEFAULT_INVERSE_CONDUCTION, HeatAPI.DEFAULT_INVERSE_INSULATION, ambientTempSupplier, listener);
    }

    public static BasicHeatCapacitor create(double heatCapacity, double inverseConductionCoefficient, double inverseInsulationCoefficient,
          @Nullable DoubleSupplier ambientTempSupplier, @Nullable IContentsListener listener) {
        MekanismPreconditions.checkHeatCapacity(heatCapacity);
        if (inverseConductionCoefficient < 1) {
            throw new IllegalArgumentException("Inverse conduction coefficient must be at least one");
        }
        return new BasicHeatCapacitor(heatCapacity, inverseConductionCoefficient, inverseInsulationCoefficient, ambientTempSupplier, listener);
    }

    protected BasicHeatCapacitor(double heatCapacity, double inverseConductionCoefficient, double inverseInsulationCoefficient,
          @Nullable DoubleSupplier ambientTempSupplier, @Nullable IContentsListener listener) {
        this.heatCapacity = heatCapacity;
        this.inverseConductionCoefficient = inverseConductionCoefficient;
        this.inverseInsulationCoefficient = inverseInsulationCoefficient;
        this.ambientTempSupplier = ambientTempSupplier;
        this.listener = listener;
    }

    protected double getAmbientTemperature() {
        return ambientTempSupplier == null ? HeatAPI.AMBIENT_TEMP : ambientTempSupplier.getAsDouble();
    }

    @Override
    public double getInverseConduction() {
        return inverseConductionCoefficient;
    }

    @Override
    public double getInverseInsulation() {
        return inverseInsulationCoefficient;
    }

    @Override
    public final double getHeatCapacity() {
        return heatCapacity;
    }

    public void onContentsChanged(HeatCapacitorData originalState) {
        if (listener != null) {
            listener.onContentsChanged();
        }
    }

    @Override
    public void handleHeat(double transfer, TransactionContext transaction) {
        if (Math.abs(transfer) > HeatAPI.EPSILON) {
            updateSnapshots(transaction);
            storedHeat = Math.max(0D, getHeat() + transfer);
        }
    }

    @Override
    public boolean isAmbientTemperature() {
        return Mth.equal(getTemperature(), getAmbientTemperature());
    }

    private boolean isHeatInitialized() {
        return storedHeat != -1;
    }

    @Override
    public final double getHeat() {
        if (!isHeatInitialized()) {
            //If the stored heat hasn't been initialized yet, update the stored heat based on initial capacity
            storedHeat = Math.max(0D, getHeatCapacity() * getAmbientTemperature());
        }
        return storedHeat;
    }

    @Override
    public void setHeat(double heat, @Nullable TransactionContext transaction) {
        MekanismPreconditions.checkNonNegative(heat);
        if (transaction == null) {
            HeatCapacitorData originalState = createSnapshot();
            storedHeat = heat;
            //TODO - 26.3: do we need a way to avoid calling onContentsChange when loading from disk? I don't think we used to have one but it might be useful to have
            onContentsChanged(originalState);
        } else {
            updateSnapshots(transaction);
            storedHeat = heat;
        }
    }

    public void updateHeatAndCapacity(double newCapacity, @Nullable TransactionContext transaction) {
        if (isHeatInitialized()) {
            //If the heat has been initialized, calculate the value the heat should have, and also update the capacity
            try (Transaction subTransaction = Transaction.open(transaction)) {
                //Ensure there is a snapshot from before we call getHeat
                updateSnapshots(subTransaction);
                double capacityChange = newCapacity - getHeatCapacity();
                setHeatAndCapacity(Math.max(0D, getHeat() + capacityChange * getAmbientTemperature()), newCapacity, subTransaction);
                subTransaction.commit();
            }
        } else {
            //If heat hasn't been initialized yet, just update the capacity
            setHeatCapacity(newCapacity, transaction);
        }
    }

    @Override
    public void setHeatCapacity(double newCapacity, @Nullable TransactionContext transaction) {
        MekanismPreconditions.checkHeatCapacity(newCapacity);
        if (transaction == null) {
            HeatCapacitorData originalState = createSnapshot();
            heatCapacity = newCapacity;
            onContentsChanged(originalState);
        } else {
            //If we are in a transactional context, update the snapshot of the heat capacity before updating the value
            updateSnapshots(transaction);
            heatCapacity = newCapacity;
        }
    }

    @Override
    protected HeatCapacitorData createSnapshot() {
        if (isHeatInitialized()) {
            return new HeatCapacitorData(getHeat(), heatCapacity);
        }
        return new HeatCapacitorData(heatCapacity);
    }

    @Override
    protected void revertToSnapshot(HeatCapacitorData snapshot) {
        //Bypass contents change check
        storedHeat = snapshot.heat().orElse(-1);
        heatCapacity = snapshot.capacity();
    }

    @Override
    protected void onRootCommit(HeatCapacitorData originalState) {
        super.onRootCommit(originalState);
        //TODO - 26.3 (heat): Should this use Mth#equal? I suspect no? Then tiny changes would potentially never get saved,
        // as it compares against last value rather than last saved value and we are checking the Mth#equal in the setHeat method
        if (storedHeat != originalState.heat().orElse(-1) || !Mth.equal(heatCapacity, originalState.capacity())) {
            //Fire content change listeners during root commit if the final state is different from the original one
            onContentsChanged(originalState);
        }
    }
}

package mekanism.common.component.containers.type;

import mekanism.api.SerializationConstants;
import mekanism.api.heat.IHeatCapacitor;
import mekanism.common.component.containers.heat.HeatCapacitorData;
import mekanism.common.registries.MekanismDataComponents;
import mekanism.common.tile.base.TileEntityMekanism;
import net.neoforged.neoforge.transfer.transaction.TransactionContext;
import org.jspecify.annotations.Nullable;

public final class HeatContainerType extends AbstractContainerType<IHeatCapacitor, HeatCapacitorData> implements ISingleContainerType<IHeatCapacitor, HeatCapacitorData> {

    HeatContainerType() {
        super(MekanismDataComponents.ATTACHED_HEAT, SerializationConstants.HEAT_CAPACITOR);
    }

    @Nullable
    @Override
    public IHeatCapacitor getContainer(TileEntityMekanism tile) {
        return tile.getHeatCapacitor();
    }

    @Override
    public void copyToContainer(IHeatCapacitor capacitor, HeatCapacitorData data) {
        if (data.heat().isPresent()) {
            capacitor.setHeatAndCapacity(data.heat().getAsDouble(), data.capacity(), null);
        } else {
            capacitor.setHeatCapacity(data.capacity(), null);
        }
    }

    @Override
    public HeatCapacitorData attachedCopyOf(IHeatCapacitor capacitor) {
        if (capacitor.isAmbientTemperature()) {
            return new HeatCapacitorData(capacitor.getHeatCapacity());
        }
        return new HeatCapacitorData(capacitor.getHeat(), capacitor.getHeatCapacity());
    }

    @Override
    public boolean canHandle(TileEntityMekanism tile) {
        return tile.canHandleHeat();
    }

    @Override
    public void copy(IHeatCapacitor from, IHeatCapacitor to, @Nullable TransactionContext transaction) {
        to.copyContents(from, transaction);
    }

    public void mergeCapacitors(@Nullable IHeatCapacitor capacitor, @Nullable IHeatCapacitor mergeCapacitor, TransactionContext transaction) {
        if (capacitor == null || mergeCapacitor == null) {
            //Nothing to do here
            //TODO: Do we want to error if they are different nullabilities?
            return;
        }
        capacitor.setHeatAndCapacity(capacitor.getHeat() + mergeCapacitor.getHeat(), capacitor.getHeatCapacity() + mergeCapacitor.getHeatCapacity(), transaction);
    }
}

package mekanism.common.component.containers.type;

import mekanism.common.tile.base.TileEntityMekanism;
import net.minecraft.core.component.DataComponentGetter;
import net.minecraft.core.component.DataComponentMap;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.neoforged.neoforge.common.util.ValueIOSerializable;
import org.jspecify.annotations.Nullable;

public interface ISingleContainerType<CONTAINER extends ValueIOSerializable, ATTACHED> extends IContainerType<CONTAINER, ATTACHED> {

    @Nullable
    CONTAINER getContainer(TileEntityMekanism tile);

    @Override
    default void copyToTile(TileEntityMekanism tile, DataComponentGetter componentGetter) {
        ATTACHED attachedData = componentGetter.get(getComponentType());
        if (attachedData != null) {
            CONTAINER container = getContainer(tile);
            if (container != null) {
                copyToContainer(container, attachedData);
            }
        }
    }

    default void copyToContainer(CONTAINER container, DataComponentGetter componentGetter) {
        ATTACHED attachedData = componentGetter.get(getComponentType());
        if (attachedData != null) {
            copyToContainer(container, attachedData);
        }
    }

    void copyToContainer(CONTAINER container, ATTACHED attached);

    @Override
    default void copyFromTile(TileEntityMekanism tile, DataComponentMap.Builder builder) {
        CONTAINER container = getContainer(tile);
        if (container != null) {
            ATTACHED attachedData = copyFromTile(tile, container);
            if (attachedData != null) {
                builder.set(getComponentType(), attachedData);
            }
        }
    }

    @Nullable
    default ATTACHED copyFromTile(TileEntityMekanism tile, CONTAINER container) {
        return attachedCopyOf(container);
    }

    @Nullable
    ATTACHED attachedCopyOf(CONTAINER container);

    default void attachCopyToStack(CONTAINER container, ItemStack stack) {
        ATTACHED attached = attachedCopyOf(container);
        if (attached != null) {
            stack.set(getComponentType(), attached);
        }
    }

    @Override
    default void saveTo(ValueOutput output, TileEntityMekanism tile) {
        saveTo(output, getContainer(tile));
    }

    default void saveTo(ValueOutput output, @Nullable CONTAINER container) {
        if (container != null) {
            String containerTag = getTag();
            ValueOutput storedContainer = output.child(containerTag);
            container.serialize(storedContainer);
            if (storedContainer.isEmpty()) {
                output.discard(containerTag);
            }
        }
    }

    @Override
    default void readFrom(ValueInput input, TileEntityMekanism tile) {
        readFrom(input, getContainer(tile));
    }

    default void readFrom(ValueInput input, @Nullable CONTAINER container) {
        if (container != null) {
            input.child(getTag()).ifPresent(container::deserialize);
        }
    }
}

package mekanism.common.component.containers.heat;

import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import io.netty.buffer.ByteBuf;
import java.util.Optional;
import java.util.OptionalDouble;
import mekanism.api.MekanismPreconditions;
import mekanism.api.SerializationConstants;
import mekanism.api.SerializerHelper;
import mekanism.api.heat.HeatAPI;
import mekanism.common.network.PacketUtils;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.util.Mth;

public record HeatCapacitorData(OptionalDouble heat, double capacity) {

    public static final Codec<HeatCapacitorData> CODEC = RecordCodecBuilder.create(instance -> instance.group(
          SerializerHelper.NON_NEGATIVE_DOUBLE.optionalFieldOf(SerializationConstants.HEAT_STORED).forGetter(data -> data.heat.isPresent() ? Optional.of(data.heat.getAsDouble()) : Optional.empty()),
          SerializerHelper.ONE_OR_GREATER_DOUBLE.optionalFieldOf(SerializationConstants.HEAT_CAPACITY, 1D).forGetter(HeatCapacitorData::capacity)
    ).apply(instance, (heat, capacity) -> new HeatCapacitorData(
          heat.map(OptionalDouble::of).orElseGet(OptionalDouble::empty),
          capacity
    )));
    public static final StreamCodec<ByteBuf, HeatCapacitorData> STREAM_CODEC = StreamCodec.composite(
          PacketUtils.OPTIONAL_DOUBLE_STREAM_CODEC, HeatCapacitorData::heat,
          ByteBufCodecs.DOUBLE, HeatCapacitorData::capacity,
          HeatCapacitorData::new
    );

    public HeatCapacitorData(double heat, double capacity) {
        this(OptionalDouble.of(heat), capacity);
    }

    public HeatCapacitorData(double capacity) {
        this(OptionalDouble.empty(), capacity);
    }

    public HeatCapacitorData {
        if (heat.isPresent()) {
            MekanismPreconditions.checkNonNegative(heat.getAsDouble());
        }
        MekanismPreconditions.checkHeatCapacity(capacity);
    }

    public HeatCapacitorData withHeat(double heat) {
        MekanismPreconditions.checkNonNegative(heat);
        if (Mth.equal(heatOrAmbient(), heat)) {
            return this;
        }
        return new HeatCapacitorData(heat, capacity);
    }

    public HeatCapacitorData withCapacity(double heatCapacity) {
        MekanismPreconditions.checkHeatCapacity(heatCapacity);
        if (Mth.equal(capacity, heatCapacity)) {
            return this;
        }
        return new HeatCapacitorData(heat, heatCapacity);
    }

    public double temperature() {
        if (heat.isPresent()) {
            return heat.getAsDouble() / capacity;
        }
        return HeatAPI.AMBIENT_TEMP;
    }

    public double heatOrAmbient() {
        if (heat.isPresent()) {
            return heat.getAsDouble();
        }
        return HeatAPI.AMBIENT_TEMP * capacity;
    }
}

package mekanism.api.heat;

import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import mekanism.api.MekanismPreconditions;
import mekanism.api.SerializationConstants;
import mekanism.api.SerializerHelper;
import net.minecraft.util.Mth;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.neoforged.neoforge.common.util.ValueIOSerializable;
import net.neoforged.neoforge.transfer.transaction.Transaction;
import net.neoforged.neoforge.transfer.transaction.TransactionContext;
import org.jspecify.annotations.Nullable;

public interface IHeatCapacitor extends ValueIOSerializable, IHeatHandler {

    /// {@return the inverse insulation coefficient for this capacitor} The larger the value the less heat dissipates into the environment.
    double getInverseInsulation();

    /// {@return heat stored in this capacitor}
    double getHeat();

    @Override
    default double getTemperature() {
        return getHeat() / getHeatCapacity();
    }

    /// Overrides the amount of heat in this [IHeatCapacitor].
    ///
    /// @param heat        Heat to set this capacitor's storage to. **Must be at least 0**.
    /// @param transaction The transaction that this operation is part of if any. May be `null`
    ///
    /// @throws IllegalArgumentException If heat is less than zero. See also [MekanismPreconditions#checkNonNegative(double)] to help perform this check.
    /// @since 10.8.0
    void setHeat(double heat, @Nullable TransactionContext transaction);

    /// Overrides the heat capacity of this [IHeatCapacitor].
    ///
    /// @param newCapacity Heat capacity to set this capacitor to. **Must be at least 1**.
    /// @param transaction The transaction that this operation is part of if any. May be `null`
    ///
    /// @throws IllegalArgumentException If heat capacity is less than one. See also [MekanismPreconditions#checkHeatCapacity(double)] to help perform this check.
    /// @since 10.8.0
    void setHeatCapacity(double newCapacity, @Nullable TransactionContext transaction);

    /// Overrides the heat and heat capacity of this [IHeatCapacitor].
    ///
    /// @param heat         Heat to set this capacitor's storage to. **Must be at least 0**.
    /// @param heatCapacity Heat capacity to set this capacitor to. **Must be at least 1**.
    /// @param transaction  The transaction that this operation is part of if any. May be `null`
    ///
    /// @throws IllegalArgumentException If heat is less than zero, or heat capacity is less than one. See also [MekanismPreconditions#checkNonNegative(double)] and
    /// [MekanismPreconditions#checkHeatCapacity(double)] to help perform this check.
    /// @since 10.8.0
    default void setHeatAndCapacity(double heat, double heatCapacity, @Nullable TransactionContext transaction) {
        try (Transaction subTransaction = Transaction.open(transaction)) {
            setHeatCapacity(heatCapacity, subTransaction);
            setHeat(heat, subTransaction);
            //Ensure that no onContentsChange is fired until after both have been updated (in case the transaction is null)
            subTransaction.commit();
        }
    }

    /// Checks if this heat capacitor is currently at the ambient temperature of its surroundings.
    ///
    /// @return `true` if this capacitor is currently at the ambient temperature of the environment it is in.
    ///
    /// @implNote This method should be overridden to take into account any variable ambient temperature data such as biomes.
    /// @since 10.7.15
    default boolean isAmbientTemperature() {
        return Mth.equal(getTemperature(), HeatAPI.AMBIENT_TEMP);
    }

    @Override
    default void serialize(ValueOutput output) {
        output.store(SerializationConstants.STATE, CapacitorState.CODEC, new CapacitorState(getHeat(), getHeatCapacity()));
    }

    @Override
    default void deserialize(ValueInput input) {
        input.read(SerializationConstants.STATE, CapacitorState.CODEC).ifPresent(state -> setHeatAndCapacity(state.heat(), state.heatCapacity(), null));
    }

    /// Helper method to copy all pertinent data from another [`heat capacitor`][IHeatCapacitor] to this one without requiring a serialization, deserialization cycle.
    ///
    /// @param other       Capacitor to copy data from.
    /// @param transaction The transaction that this operation is part of. May be `null`, and also the implementation may not fully support rolling back the transaction.
    ///
    /// @implSpec If [#serialize] is overridden, this method should be overridden as well to transfer the relevant data.
    /// @see HeatCapacitorWrapper#getInternal() Getting the internal capacitor when wrapped if instance checks are necessary.
    /// @since 10.8.0
    default void copyContents(IHeatCapacitor other, @Nullable TransactionContext transaction) {
        setHeatAndCapacity(other.getHeat(), other.getHeatCapacity(), transaction);
    }

    /// Helper record for use in serialization to represent a heat capacitor's state.
    ///
    /// @since 10.8.0
    record CapacitorState(double heat, double heatCapacity) {

        /// Codec for serializing and deserializing a heat capacitor's state.
        public static final Codec<CapacitorState> CODEC = RecordCodecBuilder.create(instance -> instance.group(
              SerializerHelper.NON_NEGATIVE_DOUBLE.optionalFieldOf(SerializationConstants.HEAT_STORED, 0D).forGetter(CapacitorState::heat),
              SerializerHelper.ONE_OR_GREATER_DOUBLE.optionalFieldOf(SerializationConstants.HEAT_CAPACITY, 1D).forGetter(CapacitorState::heatCapacity)
        ).apply(instance, CapacitorState::new));

        public CapacitorState {
            MekanismPreconditions.checkNonNegative(heat);
            MekanismPreconditions.checkHeatCapacity(heatCapacity);
        }
    }
}

package mekanism.common.capabilities.heat;

import mekanism.api.heat.HeatAPI;
import mekanism.api.heat.HeatAPI.HeatTransfer;
import mekanism.api.heat.IHeatCapacitor;
import mekanism.api.heat.IHeatHandler;
import mekanism.common.util.EnumUtils;
import net.minecraft.core.Direction;
import net.neoforged.neoforge.transfer.transaction.TransactionContext;
import org.jspecify.annotations.Nullable;

@FunctionalInterface
public interface ITileHeatHandler {

    /// Gets the [IHeatHandler] adjacent to this [ITileHeatHandler].
    ///
    /// @param side The side of this [ITileHeatHandler] to look on.
    ///
    /// @return The [IHeatHandler] adjacent to this [ITileHeatHandler], otherwise returns `null`.
    ///
    /// @implSpec If this method is called it can be assumed the handler has been checked as supporting heat.
    @Nullable
    default IHeatHandler getAdjacent(Direction side) {
        return null;
    }

    /// {@return the [IHeatCapacitor] on the given side}
    ///
    /// @param side The side we are interacting with the handler from (null for internal).
    @Nullable
    IHeatCapacitor getHeatCapacitor(@Nullable Direction side);

    /// Simulate heat transfers
    default HeatTransfer simulate(TransactionContext transaction) {
        return new HeatTransfer(simulateAdjacent(transaction), simulateEnvironment(transaction));
    }

    default double getAmbientTemperature(Direction side) {
        return HeatAPI.AMBIENT_TEMP;
    }

    default double simulateEnvironment(TransactionContext transaction) {
        double environmentTransfer = 0;
        for (Direction side : EnumUtils.DIRECTIONS) {
            IHeatCapacitor heatCapacitor = getHeatCapacitor(side);
            if (heatCapacitor == null) {
                continue;
            }
            double heatCapacity = heatCapacitor.getHeatCapacity();
            //transfer to air otherwise
            double invConduction = HeatAPI.AIR_INVERSE_COEFFICIENT + heatCapacitor.getInverseInsulation() + heatCapacitor.getInverseConduction();
            //transfer heat difference based on environment temperature (ambient)
            double tempToTransfer = (heatCapacitor.getTemperature() - getAmbientTemperature(side)) / invConduction;
            heatCapacitor.handleHeat(-tempToTransfer * heatCapacity, transaction);
            if (tempToTransfer > 0) {
                //Only count it towards environmental loss if it is hotter than the ambient temperature
                environmentTransfer += tempToTransfer;
            }
        }
        return environmentTransfer;
    }

    default double simulateAdjacent(TransactionContext transaction) {
        double adjacentTransfer = 0;
        for (Direction side : EnumUtils.DIRECTIONS) {
            IHeatCapacitor heatCapacitor = getHeatCapacitor(side);
            if (heatCapacitor == null) {
                continue;
            }
            //Note: We can safely call getAdjacent as we know we supuport heat transfers on the side due to having a heat capacitor
            IHeatHandler sink = getAdjacent(side);
            if (sink == null) {
                continue;
            }
            double temp = heatCapacitor.getTemperature();
            double sinkTemp = sink.getTemperature();
            if (temp <= sinkTemp) {
                //If our temperature is lower than the sink, we skip calculating what the adjacent loss to the sink
                // is as if the sink is able to have heat transferred away from it (which is a bit of a weird concept
                // in relation to thermodynamics, but makes some sense with our implementation), it will be handled by
                // the sink when the sink simulates adjacent heat transfers. This also prevents us from having heat
                // transfers effectively happen "twice" per tick rather than just once
                // Note: We also skip if our temp is equal to the sink's temperature so that we can short circuit
                // past the following logic
                continue;
            }
            double heatCapacity = heatCapacitor.getHeatCapacity();
            double sinkHeatCapacity = sink.getHeatCapacity();
            //Calculate the target temperature using calorimetry
            double finalTemp = (temp * heatCapacity + sinkTemp * sinkHeatCapacity) / (heatCapacity + sinkHeatCapacity);
            double invConduction = sink.getInverseConduction() + heatCapacitor.getInverseConduction();
            double tempToTransfer = (temp - finalTemp) / invConduction;
            double heatToTransfer = tempToTransfer * heatCapacity;
            heatCapacitor.handleHeat(-heatToTransfer, transaction);
            sink.handleHeat(heatToTransfer, transaction);
            if (tempToTransfer != 0 && countsAsAdjacent(side)) {
                adjacentTransfer += tempToTransfer;
            }
        }
        return adjacentTransfer;
    }

    default boolean countsAsAdjacent(Direction side) {
        return true;
    }
}

package mekanism.common.capabilities.heat;

import java.util.Arrays;
import java.util.function.DoubleSupplier;
import java.util.function.Supplier;
import mekanism.api.heat.HeatAPI;
import mekanism.common.util.EnumUtils;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.world.level.Level;
import org.jspecify.annotations.Nullable;

public class CachedAmbientTemperature implements DoubleSupplier {

    private final double[] ambientTemperature = new double[EnumUtils.DIRECTIONS.length + 1];
    private final Supplier<@Nullable Level> worldSupplier;
    private final Supplier<BlockPos> positionSupplier;

    public CachedAmbientTemperature(Supplier<@Nullable Level> worldSupplier, Supplier<BlockPos> positionSupplier) {
        this.worldSupplier = worldSupplier;
        this.positionSupplier = positionSupplier;
        Arrays.fill(ambientTemperature, -1);
    }

    @Override
    public double getAsDouble() {
        return getTemperature(null);
    }

    public double getTemperature(@Nullable Direction side) {
        int index = side == null ? EnumUtils.DIRECTIONS.length : side.ordinal();
        double biomeAmbientTemp = ambientTemperature[index];
        if (biomeAmbientTemp == -1) {
            Level world = worldSupplier.get();
            if (world == null) {
                return HeatAPI.AMBIENT_TEMP;
            }
            BlockPos pos = positionSupplier.get();
            if (side != null) {
                pos = pos.relative(side);
            }
            return ambientTemperature[index] = HeatAPI.getAmbientTemp(world, pos);
        }
        return biomeAmbientTemp;
    }
}

